1	/**
2	 * Kleine, wiederverwendbare Badges nach den Design-Regeln aus docs/pfade/PFAD-D.md:
3	 * Evidenzstufe mit Klartext + Tooltip, Status, Konflikt. Eine Datei, weil Liste
4	 * (D2) und Detailseite (D3) dieselben Badges brauchen.
5	 */
6	import type { EvidenceLevel, RequirementStatus, SourceType } from "@/src/lib/api";
7	
8	const EVIDENCE_STYLE: Record<EvidenceLevel, { label: string; className: string }> = {
9	  A: { label: "A · strong", className: "bg-emerald-100 text-emerald-800 border-emerald-300" },
10	  B: { label: "B · medium", className: "bg-blue-100 text-blue-800 border-blue-300" },
11	  C: { label: "C · weak", className: "bg-amber-100 text-amber-800 border-amber-300" },
12	  D: { label: "D · assumption", className: "bg-zinc-100 text-zinc-600 border-zinc-300" },
13	};
14	
15	/** `reason` ist der Begründungssatz (Requirement.rationale), damit die Zahl eine Herkunft hat. */
16	export function EvidenceBadge({ level, reason }: { level: EvidenceLevel; reason?: string }) {
17	  const style = EVIDENCE_STYLE[level];
18	  return (
19	    <span
20	      title={reason}
21	      className={`inline-flex items-center rounded-full border px-2 py-0.5 text-xs font-medium ${style.className}`}
22	    >
23	      {style.label}
24	    </span>
25	  );
26	}
27	
28	const STATUS_STYLE: Record<RequirementStatus, { label: string; className: string }> = {
29	  proposed: { label: "Proposed", className: "bg-zinc-100 text-zinc-700 border-zinc-300" },
30	  challenged: { label: "Challenged", className: "bg-amber-100 text-amber-800 border-amber-300" },
31	  approved: { label: "Approved", className: "bg-emerald-100 text-emerald-800 border-emerald-300" },
32	  rejected: { label: "Rejected", className: "bg-rose-100 text-rose-800 border-rose-300" },
33	};
34	
35	export function StatusBadge({ status }: { status: RequirementStatus }) {
36	  const style = STATUS_STYLE[status];
37	  return (
38	    <span
39	      className={`inline-flex items-center rounded-full border px-2 py-0.5 text-xs font-medium ${style.className}`}
40	    >
41	      {style.label}
42	    </span>
43	  );
44	}
45	
46	/** Gelbes Badge, falls ein verknüpfter Befund `conflicts_with` hat (Design-Regel PFAD-D). */
47	export function ConflictBadge({ conflictingTitles }: { conflictingTitles: string[] }) {
48	  if (conflictingTitles.length === 0) return null;
49	  return (
50	    <span
51	      title={`Conflicting evidence: ${conflictingTitles.join(", ")}`}
52	      className="inline-flex items-center gap-1 rounded-full border border-yellow-300 bg-yellow-100 px-2 py-0.5 text-xs font-medium text-yellow-800"
53	    >
54	      ⚠ Conflicting evidence
55	    </span>
56	  );
57	}
58	
59	const CATEGORY_LABELS: Record<string, string> = {
60	  exterior: "Exterior",
61	  interior: "Interior",
62	  comfort_space: "Comfort & space",
63	  infotainment_digital: "Infotainment & digital",
64	  driving_experience: "Driving experience",
65	  range_charging: "Range & charging",
66	  driver_assistance: "Driver assistance",
67	  quality_perception: "Quality perception",
68	  variants_packages: "Variants & packages",
69	};
70	
71	export function categoryLabel(category: string): string {
72	  return CATEGORY_LABELS[category] ?? category;
73	}
74	
75	/**
76	 * Vertrauensstufe pro Beleg, abgeleitet aus den Regeln in
77	 * requirements_engine/evidence_level.py (BMW_SOURCES zählen mehr als Web, Web bestätigt nur,
78	 * Absatz/Optionsliste sind Kontext, kein Kundenbeleg). Keine neue Regel, nur die bestehende
79	 * für den Detailbildschirm sichtbar gemacht.
80	 */
81	const SOURCE_TRUST: Record<SourceType, { label: string; hint: string; className: string }> = {
82	  feedback: {
83	    label: "BMW customer data",
84	    hint: "Direct customer feedback; counts toward the evidence level.",
85	    className: "bg-emerald-50 text-emerald-700 border-emerald-300",
86	  },
87	  study: {
88	    label: "BMW customer data",
89	    hint: "BMW customer study; counts toward the evidence level.",
90	    className: "bg-emerald-50 text-emerald-700 border-emerald-300",
91	  },
92	  web: {
93	    label: "External · confirms only",
94	    hint: "Web source. Can confirm a finding but never carries it alone.",
95	    className: "bg-amber-50 text-amber-700 border-amber-300",
96	  },
97	  sales: {
98	    label: "Context data",
99	    hint: "Sales volume, not direct customer feedback.",
100	    className: "bg-zinc-50 text-zinc-600 border-zinc-300",
101	  },
102	  option_list: {
103	    label: "Context data",
104	    hint: "Today's options list, not direct customer feedback.",
105	    className: "bg-zinc-50 text-zinc-600 border-zinc-300",
106	  },
107	};
