109	export function SourceTrustBadge({ sourceType }: { sourceType: SourceType }) {
110	  const style = SOURCE_TRUST[sourceType];
111	  return (
112	    <span
113	      title={style.hint}
114	      className={`inline-flex items-center rounded-full border px-2 py-0.5 text-xs font-medium ${style.className}`}
115	    >
